import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")
    with open(file_path, "r") as f:
        data = json.load(f)
    if INPUT_JSON.get("type") == "object" and not isinstance(data, dict):
        raise ValueError("JSON root is not an object")
    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")
    properties = INPUT_JSON.get("properties", {})
    for field, rules in properties.items():
        if field in data and "type" in rules:
            expected_type = rules["type"]
            if not isinstance(data[field], expected_type):
                raise ValueError(f"Field '{field}' expected type {expected_type.__name__}, got {type(data[field]).__name__}")
    email_value = data.get("email")
    if email_value is not None:
        if not isinstance(email_value, str) or not re.match(EMAIL_REGEX, email_value):
            raise ValueError("Invalid email format")
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")
    expected_rule = properties.get(attribute)
    if expected_rule and "type" in expected_rule:
        expected_type = expected_rule["type"]
        if not isinstance(data[attribute], expected_type):
            raise ValueError(f"Requested attribute '{attribute}' does not match expected type {expected_type.__name__}")
    return data[attribute]
